/// <summary>
/// Transfer Order Load Planning AID lines TMP
/// </summary>
/// <returns>METTransferOrderLoadPlanningAidLinesTmp</returns>
[SRSReportDataSetAttribute(tablestr(METTransferOrderLoadPlanningAidLinesTmp))]
public METTransferOrderLoadPlanningAidLinesTmp getLines()
{
    select transferOrderLoadPlanningAidLinesTmp;
    return transferOrderLoadPlanningAidLinesTmp;
}

/// <summary> /// Parses the report parameters and fills the <c>transferOrderLoadPlanningAidLinesTmp</c> tables with data. /// </summary> public void processReport() { contract = this.parmDataContract() as METTransferOrderLoadPlanningContract; CreatedTransactionId createdTransactionId = contract.parmTransaction();
METTransferOrderLoadPlanningAidLines metTransferOrderLoadPlanningAidLinesTmp;
transferOrderLoadPlanningAidLinesTmp.setConnection(this.parmUserConnection());
insert_recordset transferOrderLoadPlanningAidLinesTmp (Cases, Eaches, RouteStop, Weight, Cube, Pallets, OrderCreatedDateTIme, OrderSplitCategoryCode, ToWarehouseNumber, ToWareHouseName, TransferId, LineRecId, HeaderRecId, InventLocationIdFrom, LineNum, Route, FromWareHouseName, ReportGeneratedDateTime, DeliveryDate, TotalRouteStops, CompanyName) select Cases, Eaches, RouteStop, Weight, Cube, Pallets, OrderCreatedDateTIme, OrderSplitCategoryCode, ToWarehouseNumber, ToWareHouseName, TransferId, LineRecId, HeaderRecId, InventLocationIdFrom, LineNum, Route, FromWareHouseName, ReportGeneratedDateTime, DeliveryDate, TotalRouteStops, CompanyName from metTransferOrderLoadPlanningAidLinesTmp where metTransferOrderLoadPlanningAidLinesTmp.CreatedTransactionId == createdTransactionId;
//Delete records from controller delete_from metTransferOrderLoadPlanningAidLinesTmp where metTransferOrderLoadPlanningAidLinesTmp.CreatedTransactionId == createdTransactionId; }
